---RefreshUI
---@param suitData table {suitId, equipIdList, playerEquipmentCoreId, name (非当前涂鸦)}
---@param position number
function UICultivateEquipDiySuitSuitNodeMB:RefreshUI(suitData, position)
    self.position = position
    local suitId  = suitData.suitId
    local isEmpty = suitId == EmptyDiySuitFlag
    if self.EmptySuitNode then
        KTool.SetActive(self.EmptySuitNode.gameObject, isEmpty)
    end

    local isSuitInfo = suitId >= CurrentDiySuitFlag
    KTool.SetActive(self.SuitInfoNode.gameObject, isSuitInfo)

    KTool.SetActive(self.LinkIcon.gameObject, false)
    KTool.SetActive(self.ActiveFlag.gameObject, false)
    if isEmpty then return end
    local equipIdList = suitData.equipIdList
    local equipDojoList = {}
    local suitId2Count = {}
    local isLink = false
    for i = 1, Constants.CardEquipmentNo do
        local playerEquipId = checkNumber(equipIdList[i])
        if playerEquipId > 0 then
            local dojo = equipComp:GetEquipById(playerEquipId)
            equipDojoList[i] = dojo

            ---@type EquipVo
            local equipVo = cardConfMgr:GetEquipVoById(dojo.equipmentId)
            local count = suitId2Count[equipVo.suitId]
            suitId2Count[equipVo.suitId] = count and (count + 1) or 1

            if checkNumber(dojo.playerCardId) > 0 then
                isLink = true
            end
        end
    end

    local playerEquipmentCoreId = suitData.playerEquipmentCoreId
    ---@type EquipmentCoreDojo
    local equipmentCoreDojo = equipComp:GetEquipCoreById(playerEquipmentCoreId)
    if equipmentCoreDojo and checkNumber(equipmentCoreDojo.playerCardId) > 0 then
        isLink = true
    end
    self:RefreshSuitInfoNode(suitData, equipmentCoreDojo, equipDojoList, suitId2Count, isLink)

end

function UICultivateEquipDiySuitSuitNodeMB:RefreshSuitInfoNode(suitData, equipmentCoreDojo, equipDojoList, suitId2Count, isLink, lock)
    KTool.SetActive(self.Container.gameObject, not checkBool(lock))
    if lock then
        return
    end

    local suitId    = suitData.suitId
    local isCurrent = suitId == CurrentDiySuitFlag
    KTool.SetActive(self.TxtCurrent.gameObject, isCurrent)

    local suitIsCurEquip = checkBool(suitData.suitIsCurEquip)
    KTool.SetActive(self.LinkIcon.gameObject, suitIsCurEquip or (isLink and not isCurrent))
    -- if suitIsCurEquip then
    --     self.LinkIcon.Status = 2
    -- elseif isLink and not isCurrent then
    --     self.LinkIcon.Status = 1
    -- end

    local isActiveCore, coreSuitId = self:CheckSuitIsActive(equipmentCoreDojo, suitId2Count)

    local isOwnCore = equipmentCoreDojo ~= nil
    local isActive = isActiveCore and isOwnCore
    KTool.SetActive(self.ActiveFlag.gameObject, isActive)
    --KTool.SetActive(self.TextNoCore.gameObject, not isActive)

    local isShowName = suitData.name ~= nil
    KTool.SetActive(self.NameText.gameObject, isShowName)
    if isShowName then
        self.NameText.text = suitData.name
    end

    --self.ImgStatusBar.Status = isActive and 2 or 1
    KTool.SetActive(self.ImgEmptyCore.gameObject,  not isActive)
    KTool.SetActive(self.CoreIcon.gameObject,  isOwnCore)
    if isOwnCore then
        ---@type GoodsVo
        local goodsVo = goodsConfMgr:GetGoodsVoById(equipmentCoreDojo.equipmentCoreId)
        self.CoreIcon:LoadSprite(goodsVo.photoPath)
        self.CoreQuality.Status = goodsVo.quality
    end

    for i = 1, Constants.CardEquipmentNo do
        self:RefreshEquipmentPartStateUI(equipDojoList[i], i, isActive, coreSuitId)
    end

    return isActive
end

---FreshCoreType
---@param occupationId number    职业id
function UICultivateEquipDiySuitSuitNodeMB:RefreshCoreType(occupationId)
    ---@type UICultivateCareerTypeNode
    local mbEnv = CfUtils.GetLuaScr(self.TypeBg.gameObject, UICultivateCareerTypeNodePath)
    if mbEnv == nil then
        return
    end

    mbEnv:RefreshUI(occupationId)
end

---RefreshEquipmentPartStateUI
---@param dojo EquipDojo
---@param part number 装备位置
function UICultivateEquipDiySuitSuitNodeMB:RefreshEquipmentPartStateUI(dojo, part, isActiveCore, suitId)
    local isOwnEquip = dojo ~= nil
    local rare = 0
    -- local equipSuitId
    local iconPath
    if isOwnEquip then
        local equipmentId = dojo.equipmentId
        ---@type EquipVo
        local equipVo = cardConfMgr:GetEquipVoById(equipmentId)
        rare = equipVo.rare
        -- equipSuitId = equipVo.suitId
        ---@type GoodsVo
        local goodsVo = goodsConfMgr:GetGoodsVoById(equipmentId)
        iconPath = goodsVo.photoPath
    end

    -- local isActiveEquip = isActiveCore and (equipSuitId ~= nil and suitId ~= nil and suitId == equipSuitId)
    -- local isActivePartPoint = isOwnEquip and isActiveEquip
    ---@type Game.Native.Common.UISwitchImage
    --local EquipmentPartStateNode = self[string.format("ImgPoint%s", part)]
    --EquipmentPartStateNode.Status = isActivePartPoint and 2 or 1

    local EquipNode         = self[string.format("Equipment%s", part)]
    local EmptyEquipPartImg = self[string.format("ImgEquipPart%s", part)]
    KTool.SetActive(EquipNode.gameObject, isOwnEquip)
    KTool.SetActive(EmptyEquipPartImg.gameObject, not isOwnEquip)
    if isOwnEquip then
        ---@type UICultivateEquipDiySuitEquipNode
        local env = CfUtils.GetLuaScr(EquipNode, EquipNodeEnvPath)
        if not isNull(env) then
            env:RefreshUI(rare, iconPath)
        end
    end

end

---RefreshSelectState
---刷新节点选中状态
---@param isSelect boolean 是否选中
function UICultivateEquipDiySuitSuitNodeMB:RefreshSelectState(isSelect)
    KTool.SetActive(self.SelectImg.gameObject, isSelect)
end

function UICultivateEquipDiySuitSuitNodeMB:CheckSuitIsActive(equipmentCoreDojo, suitId2Count)
    local suitId
    local isActiveCore = false
    if equipmentCoreDojo then
        local refId = equipmentCoreDojo.equipmentCoreId
        ---@type EquipCoreVo
        local equipCoreVo = cardConfMgr:GetEquipCoreVoById(refId)
        suitId = equipCoreVo.suitId

        local count = suitId2Count[suitId] or 0
        isActiveCore = EquipUtils.CheckCoreIsUnLock(refId, count)
    end
    return isActiveCore, suitId
end

